  function resolveJsPdfConstructor() {
    if (window.jspdf && typeof window.jspdf.jsPDF === 'function') return window.jspdf.jsPDF;
    if (window.jspdf && typeof window.jspdf.default === 'function') return window.jspdf.default;
    if (typeof window.jsPDF === 'function') return window.jsPDF;
    return null;
  }

  function loadJsPdfLibrary() {
    var existing = resolveJsPdfConstructor();
    if (existing) return Promise.resolve(existing);

    function inject(src) {
      return new Promise(function (resolve, reject) {
        var script = document.createElement('script');
        script.src = src;
        script.async = true;
        script.setAttribute('data-hub-jspdf', '1');
        script.onload = function () {
          var JsPDF = resolveJsPdfConstructor();
          if (JsPDF) resolve(JsPDF);
          else reject(new Error('PDF engine loaded but jsPDF was not found.'));
        };
        script.onerror = function () {
          reject(new Error('PDF engine failed to load from ' + src));
        };
        document.head.appendChild(script);
      });
    }

    // Prefer same-origin vendor copy (html2pdf bundle does not expose jsPDF on window)
    var localSrc = '/js/vendor/jspdf.umd.min.js';
    try {
      localSrc = new URL('/js/vendor/jspdf.umd.min.js', window.location.origin).href;
    } catch (_e) {
      /* keep */
    }

    var pending = document.querySelector('script[data-hub-jspdf]');
    if (pending) {
      return new Promise(function (resolve, reject) {
        pending.addEventListener('load', function () {
          var JsPDF = resolveJsPdfConstructor();
          if (JsPDF) resolve(JsPDF);
          else reject(new Error('PDF engine failed to load. Check your connection and try again.'));
        });
        pending.addEventListener('error', function () {
          reject(new Error('PDF engine failed to load. Check your connection and try again.'));
        });
      });
    }

    return inject(localSrc).catch(function () {
      return inject('https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js');
    }).catch(function () {
      throw new Error('PDF engine failed to load. Check your connection and try again.');
    });
  }

  function arrayBufferToBase64(buffer) {
    var bytes = new Uint8Array(buffer);
    var chunk = 0x8000;
    var binary = '';
    for (var i = 0; i < bytes.length; i += chunk) {
      binary += String.fromCharCode.apply(null, bytes.subarray(i, i + chunk));
    }
    return btoa(binary);
  }

  function fetchFontAsBase64(url) {
    return fetch(url, { cache: 'force-cache' })
      .then(function (res) {
        if (!res.ok) throw new Error('font_fetch');
        return res.arrayBuffer();
      })
      .then(arrayBufferToBase64);
  }

  function registerSponsorPackFonts(doc) {
    var base = '/assets/fonts/';
    try {
      base = new URL('/assets/fonts/', window.location.origin).href;
    } catch (_e) {
      /* keep */
    }
    return Promise.all([
      fetchFontAsBase64(base + 'DMSans-Regular.ttf').catch(function () {
        return '';
      }),
      fetchFontAsBase64(base + 'DMSans-Bold.ttf').catch(function () {
        return '';
      }),
      fetchFontAsBase64(base + 'DMSerifDisplay-Regular.ttf').catch(function () {
        return '';
      }),
    ]).then(function (fonts) {
      var regular = fonts[0];
      var bold = fonts[1];
      var serif = fonts[2];
      var ok = false;
      try {
        if (regular) {
          doc.addFileToVFS('DMSans-Regular.ttf', regular);
          doc.addFont('DMSans-Regular.ttf', 'DMSans', 'normal');
          ok = true;
        }
        if (bold) {
          doc.addFileToVFS('DMSans-Bold.ttf', bold);
          doc.addFont('DMSans-Bold.ttf', 'DMSans', 'bold');
          ok = true;
        }
        if (serif) {
          doc.addFileToVFS('DMSerifDisplay-Regular.ttf', serif);
          doc.addFont('DMSerifDisplay-Regular.ttf', 'DMSerif', 'normal');
        }
      } catch (_err) {
        ok = false;
      }
      return {
        sans: ok ? 'DMSans' : 'helvetica',
        serif: serif ? 'DMSerif' : 'helvetica',
        hasCustom: ok,
      };
    });
  }

  function sponsorPackPdfAddImage(doc, dataUrl, x, y, w, h) {
    if (!dataUrl) return false;
    var fmt = /image\/jpe?g/i.test(dataUrl) ? 'JPEG' : 'PNG';
    try {
      doc.addImage(dataUrl, fmt, x, y, w, h);
      return true;
    } catch (_e) {
      return false;
    }
  }

  /** Fit image into a box preserving aspect ratio. */
  function sponsorPackPdfFitImage(doc, dataUrl, boxX, boxY, boxW, boxH, pad) {
    pad = pad == null ? 2 : pad;
    if (!dataUrl) return Promise.resolve(false);
    var innerW = Math.max(1, boxW - pad * 2);
    var innerH = Math.max(1, boxH - pad * 2);
    return new Promise(function (resolve) {
      var img = new Image();
      img.onload = function () {
        var iw = img.naturalWidth || 1;
        var ih = img.naturalHeight || 1;
        var ratio = iw / ih;
        var drawW = innerW;
        var drawH = drawW / ratio;
        if (drawH > innerH) {
          drawH = innerH;
          drawW = drawH * ratio;
        }
        var dx = boxX + (boxW - drawW) / 2;
        var dy = boxY + (boxH - drawH) / 2;
        resolve(sponsorPackPdfAddImage(doc, dataUrl, dx, dy, drawW, drawH));
      };
      img.onerror = function () {
        resolve(false);
      };
      img.src = dataUrl;
    });
  }

  function sponsorPackPdfPlacementRows(list, labelKey, totalForPct) {
    var rows = Array.isArray(list) ? list.slice(0, 3) : [];
    var total = Number(totalForPct) || 0;
    if (!total) {
      rows.forEach(function (r) {
        total += Number(r.count) || 0;
      });
    }
    return rows.map(function (r) {
      var label =
        labelKey === 'placement'
          ? formatSponsorPlacementLabel(r.placement || r.key)
          : String(r[labelKey] || r.key || '').replace(/_/g, ' ');
      var count = Number(r.count) || 0;
      var pct = total > 0 ? Math.round((count / total) * 1000) / 10 : null;
      return {
        label: label,
        value: formatSponsorPackNumber(count) + (pct != null ? ' (' + pct + '%)' : ''),
      };
    });
  }

  function sponsorPackWrap(doc, fontName, fontStyle, fontSize, text, maxWidth) {
    doc.setFont(fontName, fontStyle);
    doc.setFontSize(fontSize);
    return doc.splitTextToSize(String(text || ''), Math.max(10, maxWidth));
  }

  /**
   * Build the client PDF with jsPDF directly (no html2canvas — avoids admin chrome clipping).
   */
  function downloadSponsorPackPdf(data, filename) {
    var brand = (data && data.brand) || {};
    var brandName = brand.company || 'Partner';
    var hubUrl = '/assets/logo-nav-transparent.png?v=20260823uk3';
    var brandUrl = brand.logoUrl || '';
    try {
      hubUrl = new URL(hubUrl, window.location.origin).href;
      if (brandUrl) brandUrl = new URL(brandUrl, window.location.origin).href;
    } catch (_e) {
      /* keep */
    }

    var summary = (data && data.summary) || {};
    var previous = (data && data.previous) || null;
    var deltas = (previous && previous.deltas) || {};
    var eng = (data && data.emailEngagement) || {};
    var contact = (data && data.contact) || {};
    var fromLabel = String((data && data.from) || '').slice(0, 10);
    var toLabel = String((data && data.to) || '').slice(0, 10);
    var periodLabel = formatSponsorPackPeriodLabel(fromLabel, toLabel);
    var theme = resolveSponsorPackTheme(data);
    var placementFilter = (data && data.placementFilter) || '';
    var tierLabel = resolveSponsorPackTierLabel(brandName, theme, placementFilter);
    var feeLabel = resolveSponsorPackFeeLabel(brandName, theme, placementFilter);
    var pageViews = Number(summary.pageVisits) || 0;
    var clicks = Number(summary.clicks) || 0;
    var siteClicks = resolveSponsorPackSiteClicks(summary);
    var logoClicks = resolveSponsorPackLogoClicks(summary, eng);
    var emails = Number(summary.emailSends) || 0;
    var opens = Number(eng.opens != null ? eng.opens : summary.emailOpens) || 0;
    var ctr = formatSponsorPackCtr(siteClicks, pageViews);
    var prepared = new Date().toLocaleString('en-GB', {
      day: 'numeric',
      month: 'short',
      year: 'numeric',
    });
    var amName = contact.name || 'Rosie McGilvray';
    var amEmail = contact.email || 'rosie@thenetworkeruk.com';
    var highlight = buildSponsorPackHighlight(
      {
        pageVisits: pageViews,
        clicks: clicks,
        siteClicks: siteClicks,
        emailLogoClicks: logoClicks,
        emailSends: emails,
        emailOpens: opens,
      },
      brandName,
      ctr,
      theme
    );

    function momHint(base, pct) {
      if (pct == null || pct === '') return base;
      return base + ' · ' + formatSponsorPackMomDelta(pct).text;
    }

    var openRateLabel =
      emails < 1 ? '—' : eng.openRatePct != null ? String(eng.openRatePct) + '%' : '0%';
    var openRateHint =
      emails < 1 ? 'No logo emails yet' : opens < 1 ? 'No opens yet' : 'Opens ÷ emails sent';
    var emailCtrLabel =
      emails < 1 ? '—' : eng.ctrPct != null ? String(eng.ctrPct) + '%' : '0%';
    var siteCtrLabel = pageViews < 1 || siteClicks < 1 ? '—' : ctr.label;
    var siteCtrHint =
      pageViews < 1
        ? 'Awaiting directory views'
        : siteClicks < 1
          ? formatSponsorPackNumber(pageViews) + ' views · no site click-throughs yet'
          : formatSponsorPackEngagementHint(siteClicks, pageViews);

    return Promise.all([
      fetchImageAsDataUrl(hubUrl)
        .then(function (d) {
          return d || fetchImageAsDataUrl('/assets/logo-nav-transparent.png?v=20260823uk3');
        })
        .catch(function () {
          return fetchImageAsDataUrl('/assets/logo-nav-transparent.png?v=20260823uk3').catch(function () {
            return '';
          });
        }),
      brandUrl
        ? fetchImageAsDataUrl(brandUrl).catch(function () {
            return '';
          })
        : Promise.resolve(''),
      loadJsPdfLibrary(),
    ]).then(function (parts) {
      var hubData = parts[0] || '';
      var brandData = parts[1] || '';
      var JsPDF = parts[2];
      var doc = new JsPDF({ unit: 'mm', format: 'a4', orientation: 'portrait' });
      return registerSponsorPackFonts(doc).then(function (fonts) {
        var SANS = fonts.sans;
        var SERIF = fonts.serif;
        var pageW = doc.internal.pageSize.getWidth();
        var pageH = doc.internal.pageSize.getHeight();
        var m = 14;
        var contentW = pageW - m * 2;
        var y = m;

        var CREAM = theme.cream;
        var CHAR = theme.char;
        var MUTED = theme.muted;
        var LAV = theme.accent;
        var LAV_DK = theme.accentDk;
        var LAV_BG = theme.accentSoft;
        var WHITE = [255, 255, 255];
        var DARK = theme.dark;

        doc.setFillColor.apply(doc, CREAM);
        doc.rect(0, 0, pageW, pageH, 'F');

        // Matched logo tiles
        var logoBoxH = 16;
        var hubBoxW = 52;
        var brandBoxW = 58;
        doc.setFillColor.apply(doc, WHITE);
        doc.setDrawColor.apply(doc, LAV);
        doc.setLineWidth(0.35);
        doc.roundedRect(m, y, hubBoxW, logoBoxH, 1.2, 1.2, 'FD');

        doc.setFont(SANS, 'bold');
        doc.setFontSize(12);
        doc.setTextColor.apply(doc, LAV_DK);
        doc.text('×', m + hubBoxW + 4, y + 10);

        var brandX = m + hubBoxW + 12;
        doc.setFillColor.apply(doc, DARK);
        doc.setDrawColor.apply(doc, DARK);
        doc.roundedRect(brandX, y, brandBoxW, logoBoxH, 1.2, 1.2, 'FD');

        doc.setDrawColor.apply(doc, LAV);
        doc.setTextColor.apply(doc, LAV_DK);
        doc.setFont(SANS, 'bold');
        doc.setFontSize(7);
        var confLabel = 'CONFIDENTIAL';
        var confW = doc.getTextWidth(confLabel) + 6;
        doc.roundedRect(pageW - m - confW, y + 4, confW, 7, 1, 1, 'S');
        doc.text(confLabel, pageW - m - confW + 3, y + 8.5);

        return Promise.all([
          sponsorPackPdfFitImage(doc, hubData, m, y, hubBoxW, logoBoxH, 2.5),
          sponsorPackPdfFitImage(doc, brandData, brandX, y, brandBoxW, logoBoxH, 2.5),
        ]).then(function (drawn) {
          if (!drawn[0]) {
            doc.setFont(SANS, 'bold');
            doc.setFontSize(8);
            doc.setTextColor.apply(doc, CHAR);
            doc.text('The Networker UK', m + 3, y + 9.5);
          }
          if (!drawn[1]) {
            doc.setFont(SANS, 'bold');
            doc.setFontSize(8);
            doc.setTextColor.apply(doc, CREAM);
            doc.text(String(brandName).slice(0, 22), brandX + 3, y + 9.5);
          }

          y += logoBoxH + 9;

          doc.setFont(SANS, 'bold');
          doc.setFontSize(8);
          doc.setTextColor.apply(doc, LAV_DK);
          doc.text('PARTNERSHIP PERFORMANCE PACK', m, y);
          y += 9;

          doc.setFont(SERIF, 'normal');
          doc.setFontSize(22);
          doc.setTextColor.apply(doc, CHAR);
          doc.text(brandName, m, y);
          y += 8;

          var meta =
            tierLabel +
            (feeLabel ? ' · ' + feeLabel : '') +
            ' · ' +
            periodLabel +
            ' · Prepared ' +
            prepared;
          var metaLines = sponsorPackWrap(doc, SANS, 'normal', 9, meta, contentW);
          doc.setTextColor.apply(doc, MUTED);
          doc.text(metaLines, m, y);
          y += metaLines.length * 4.4 + 5;

          // Highlight — wrap at draw size
          var hlPad = 5;
          var hlLines = sponsorPackWrap(doc, SANS, 'normal', 10.5, highlight, contentW - hlPad * 2);
          var hlLineH = 5.2;
          var hlH = 7 + hlLines.length * hlLineH + 6;
          doc.setFillColor.apply(doc, CHAR);
          doc.roundedRect(m, y, contentW, hlH, 1.5, 1.5, 'F');
          doc.setFont(SANS, 'bold');
          doc.setFontSize(7);
          doc.setTextColor.apply(doc, LAV);
          doc.text('KEY HIGHLIGHT', m + hlPad, y + 5);
          doc.setFont(SANS, 'normal');
          doc.setFontSize(10.5);
          doc.setTextColor.apply(doc, CREAM);
          doc.text(hlLines, m + hlPad, y + 11);
          y += hlH + 5;

          function drawKpi(x, yy, w, h, label, value, hint, accent) {
            if (accent) {
              doc.setFillColor.apply(doc, CHAR);
              doc.setDrawColor.apply(doc, CHAR);
            } else {
              doc.setFillColor.apply(doc, WHITE);
              doc.setDrawColor.apply(doc, LAV);
            }
            doc.setLineWidth(0.5);
            doc.roundedRect(x, yy, w, h, 1.5, 1.5, 'FD');
            doc.setFont(SANS, 'bold');
            doc.setFontSize(7);
            doc.setTextColor.apply(doc, accent ? [200, 180, 210] : LAV_DK);
            doc.text(String(label).toUpperCase(), x + 3.5, yy + 5);
            doc.setFont(SANS, 'bold');
            doc.setFontSize(18);
            doc.setTextColor.apply(doc, accent ? CREAM : CHAR);
            doc.text(String(value), x + 3.5, yy + 14);
            var hintLines = sponsorPackWrap(doc, SANS, 'normal', 7.5, hint, w - 7);
            doc.setTextColor.apply(doc, accent ? [210, 200, 205] : MUTED);
            doc.text(hintLines.slice(0, 3), x + 3.5, yy + 19);
          }

          var gap = 3;
          var kpiW = (contentW - gap) / 2;
          var kpiH = 30;
          drawKpi(
            m,
            y,
            kpiW,
            kpiH,
            'Directory reach',
            formatSponsorPackNumber(pageViews),
            momHint('Views of your sponsored pages', deltas.pageVisitsPct),
            false
          );
          drawKpi(
            m + kpiW + gap,
            y,
            kpiW,
            kpiH,
            'Site visits driven',
            formatSponsorPackNumber(clicks),
            momHint(sponsorPackOutboundHint(summary, eng), deltas.clicksPct),
            false
          );
          y += kpiH + gap;
          drawKpi(m, y, kpiW, kpiH, 'Site CTR', siteCtrLabel, siteCtrHint, true);
          drawKpi(
            m + kpiW + gap,
            y,
            kpiW,
            kpiH,
            'Emails with logo',
            formatSponsorPackNumber(emails),
            momHint('platform emails carrying your logo', deltas.emailSendsPct),
            false
          );
          y += kpiH + 5;

          // Email engagement
          var emailSub = 'Opens and logo taps from platform emails that included your logo';
          var emailH = 34;
          doc.setFillColor.apply(doc, WHITE);
          doc.setDrawColor.apply(doc, LAV);
          doc.setLineWidth(0.5);
          doc.roundedRect(m, y, contentW, emailH, 1.5, 1.5, 'FD');
          doc.setFillColor.apply(doc, LAV_BG);
          doc.rect(m + 0.4, y + 0.4, contentW - 0.8, 10, 'F');
          doc.setFont(SANS, 'bold');
          doc.setFontSize(8);
          doc.setTextColor.apply(doc, CHAR);
          doc.text('EMAIL ENGAGEMENT', m + 4, y + 6.5);
          var subLines = sponsorPackWrap(doc, SANS, 'normal', 7, emailSub, contentW - 55);
          doc.setTextColor.apply(doc, MUTED);
          doc.text(subLines[0] || emailSub, m + 48, y + 6.5);

          var emailMetrics = [
            { label: 'OPENS', value: formatSponsorPackNumber(opens), hint: momHint('Email opens', deltas.emailOpensPct) },
            { label: 'OPEN RATE', value: openRateLabel, hint: openRateHint },
            {
              label: 'LOGO CLICKS',
              value: formatSponsorPackNumber(logoClicks),
              hint: 'Taps on the sponsor logo in email',
            },
            {
              label: 'LOGO CTR',
              value: emailCtrLabel,
              hint: emails < 1 ? 'No logo emails yet' : 'Logo taps ÷ emails sent',
            },
          ];
          var colW = contentW / 4;
          emailMetrics.forEach(function (em, i) {
            var cx = m + i * colW;
            doc.setFont(SANS, 'bold');
            doc.setFontSize(6.5);
            doc.setTextColor.apply(doc, LAV_DK);
            doc.text(em.label, cx + colW / 2, y + 16, { align: 'center' });
            doc.setFont(SANS, 'bold');
            doc.setFontSize(14);
            doc.setTextColor.apply(doc, CHAR);
            doc.text(String(em.value), cx + colW / 2, y + 23, { align: 'center' });
            var hLines = sponsorPackWrap(doc, SANS, 'normal', 6.5, em.hint, colW - 4);
            doc.setTextColor.apply(doc, MUTED);
            doc.text(hLines[0] || '', cx + colW / 2, y + 28.5, { align: 'center' });
          });
          y += emailH + 5;

          function drawRankPanel(x, yy, w, title, rows, emptyMsg) {
            var h = 8 + Math.max(rows.length, 1) * 6.2 + 6;
            doc.setFillColor.apply(doc, WHITE);
            doc.setDrawColor(232, 226, 236);
            doc.setLineWidth(0.3);
            doc.roundedRect(x, yy, w, h, 1, 1, 'FD');
            doc.setFont(SANS, 'bold');
            doc.setFontSize(9);
            doc.setTextColor.apply(doc, CHAR);
            doc.text(title, x + 3.5, yy + 6);
            if (!rows.length) {
              doc.setFont(SANS, 'normal');
              doc.setFontSize(8);
              doc.setTextColor.apply(doc, MUTED);
              doc.text(emptyMsg, x + 3.5, yy + 13);
            } else {
              rows.forEach(function (row, idx) {
                var ry = yy + 12.5 + idx * 6.2;
                doc.setFont(SANS, 'normal');
                doc.setFontSize(8);
                doc.setTextColor.apply(doc, CHAR);
                var labelLines = sponsorPackWrap(doc, SANS, 'normal', 8, row.label, w - 28);
                doc.text(labelLines[0] || row.label, x + 3.5, ry);
                doc.setFont(SANS, 'bold');
                doc.text(row.value, x + w - 3.5, ry, { align: 'right' });
              });
            }
            return h;
          }

          var clickRows = sponsorPackPdfPlacementRows(data.byPlacement, 'placement', clicks);
          var viewRows = sponsorPackPdfPlacementRows(
            (data.impressions || {}).byPlacement,
            'placement',
            pageViews
          );
          var halfW = (contentW - gap) / 2;
          var h1 = drawRankPanel(m, y, halfW, 'Clicks by placement', clickRows, 'No outbound clicks yet.');
          var h2 = drawRankPanel(
            m + halfW + gap,
            y,
            halfW,
            'Views by placement',
            viewRows,
            'No directory views yet.'
          );
          y += Math.max(h1, h2) + 5;

          var leadsText =
            'When someone clicks your logo, we tag the visit so it appears in your Google Analytics / CRM as traffic from The Networker UK.';
          var leadsW = contentW * 0.58;
          var contactW = contentW - leadsW - gap;
          var leadsLines = sponsorPackWrap(doc, SANS, 'normal', 8.5, leadsText, leadsW - 8);
          var boxH = Math.max(24, 9 + leadsLines.length * 4.4 + 5);

          doc.setFillColor.apply(doc, LAV_BG);
          doc.roundedRect(m, y, leadsW, boxH, 1, 1, 'F');
          doc.setFont(SANS, 'bold');
          doc.setFontSize(7);
          doc.setTextColor.apply(doc, LAV_DK);
          doc.text('WHERE YOUR LEADS SHOW UP', m + 3.5, y + 5.5);
          doc.setFont(SANS, 'normal');
          doc.setFontSize(8.5);
          doc.setTextColor.apply(doc, CHAR);
          doc.text(leadsLines, m + 3.5, y + 11.5);

          doc.setFillColor.apply(doc, CHAR);
          doc.roundedRect(m + leadsW + gap, y, contactW, boxH, 1, 1, 'F');
          doc.setFont(SANS, 'bold');
          doc.setFontSize(7);
          doc.setTextColor(200, 190, 200);
          var qLines = sponsorPackWrap(doc, SANS, 'bold', 7, 'QUESTIONS ABOUT THIS PACK?', contactW - 7);
          doc.text(qLines[0], m + leadsW + gap + 3.5, y + 5.5);
          doc.setFont(SANS, 'bold');
          doc.setFontSize(11);
          doc.setTextColor.apply(doc, CREAM);
          doc.text(amName, m + leadsW + gap + 3.5, y + 13);
          doc.setFont(SANS, 'normal');
          doc.setFontSize(8.5);
          doc.setTextColor.apply(doc, LAV);
          doc.text(amEmail, m + leadsW + gap + 3.5, y + 19);

          var footY = Math.min(Math.max(y + boxH + 8, pageH - 12), pageH - 8);
          doc.setDrawColor.apply(doc, LAV);
          doc.setLineWidth(0.2);
          doc.line(m, footY - 4, pageW - m, footY - 4);
          doc.setFont(SANS, 'normal');
          doc.setFontSize(6.5);
          doc.setTextColor(122, 114, 116);
          doc.text(
            'CONFIDENTIAL · THE NETWORKER HUB × ' + String(brandName).toUpperCase(),
            m,
            footY
          );
          doc.text('thenetworkeruk.com', pageW - m, footY, { align: 'right' });

          doc.save(filename || 'sponsor-pack.pdf');
        });
      });
    });
  }

  function monthDateInputsDefault() {
    var now = new Date();
    var y = now.getUTCFullYear();
    var m = now.getUTCMonth();
    var from = new Date(Date.UTC(y, m, 1));
    var to = new Date(Date.UTC(y, m + 1, 0));
    function isoDay(d) {
      return d.toISOString().slice(0, 10);
    }
    return { from: isoDay(from), to: isoDay(to) };
  }

  function formatSponsorPackNumber(n) {
    var num = Number(n) || 0;
    try {
      return num.toLocaleString('en-GB');
    } catch (_e) {
      return String(num);
    }
  }

  function formatSponsorPlacementLabel(raw) {
    var s = String(raw || '').trim();
    if (!s || s === '(blank)') return 'Unlabelled';
    var map = {
      events_hero: 'Events hero',
      organisers_hero: 'Organisers hero',
      opportunities_hero: 'Opportunities hero',
      events_sponsor_hub: 'Events hero',
      organisers_sponsor_hub: 'Organisers hero',
      opportunities_sponsor_hub: 'Opportunities hero',
      home_partners: 'Home partners',
      events_email: 'Events emails',
      organisers_email: 'Organisers emails',
      opportunities_email: 'Opportunities emails',
      email_sponsor: 'Email sponsor',
      email_mini_sponsor: 'Email mini sponsors',
      events_email_mini: 'Event Page Partner emails',
      organisers_email_mini: 'Organiser Page Partner emails',
      opportunities_email_mini: 'Opportunity Page Partner emails',
      email2_launch: 'Email 2 launch',
      booking_email_sponsor: 'Booking email sponsor',
      page_partner_carousel: 'Page Partner (legacy)',
      page_partner: 'Page Partner (legacy)',
      page_partners: 'All Page Partners',
      events_page_partner: 'Event Page Partner',
      organisers_page_partner: 'Organiser Page Partner',
      opportunities_page_partner: 'Opportunity Page Partner',
      event_page_carousel_ads: 'Event Page Partner',
      organiser_page_carousel_ads: 'Organiser Page Partner',
      opportunity_page_carousel_ads: 'Opportunity Page Partner',
      opportunity_page_sidebar_ad: 'Opportunity Page Partner',
      email_mini_sponsors: 'Email mini sponsors',
      sponsor_sidebar: 'Sidebar sponsor',
      hub_partner_email: 'Partner emails',
    };
    if (map[s]) return map[s];
    return s.replace(/_/g, ' ');
  }

