    var labels = {
      description: 'No bio',
      logo: 'No logo',
      website: 'No website',
      email: 'No contact email',
    };
    return (
      '<span class="inline-flex items-center rounded-full bg-amber-100 text-amber-900 text-[10px] font-semibold px-2 py-0.5 mr-1">' +
      esc(labels[field] || field) +
      '</span>'
    );
